<?php

# @autogenerated
declare(strict_types=1);

namespace Civi\Lughauth\Features\Notification\SmtpOutboundConfig\Application\Policy\Allow\Delete;

use Throwable;
use Civi\Lughauth\Features\Notification\SmtpOutboundConfig\Application\Usecase\Delete\SmtpOutboundConfigDeleteAllowDecision;
use Civi\Lughauth\Shared\Context;
use Civi\Lughauth\Shared\Observability\LoggerAwareTrait;
use Civi\Lughauth\Shared\Observability\TracerAwareTrait;

class IsAuthenticatedDeleteAllow
{
    use LoggerAwareTrait;
    use TracerAwareTrait;

    public function __construct(private readonly Context $context)
    {
    }
    public function __invoke(SmtpOutboundConfigDeleteAllowDecision $proposal): SmtpOutboundConfigDeleteAllowDecision
    {
        $this->logDebug("Check IsAuthenticatedDeleteAllow Smtp outbound config");
        $span = $this->startSpan("Check IsAuthenticatedDeleteAllow Smtp outbound config");
        try {
            $userContext = $this->context->getIdentity();
            if ($proposal->isAllowed()) {
                if (! !$userContext->anonymous) {
                    $proposal->deny('Disabled if not IsAuthenticatedDelete');
                }
            }
            return $proposal;
        } catch (Throwable $ex) {
            $span->recordException($ex);
            throw $ex;
        } finally {
            $span->end();
        }
    }
}
